insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('flowassurance', 'intermediate', 'module', 'm01-steady-state', 1, 'The steady state energy balance sets m Cp dT/dx against minus U pi D times the excess over ambient. What does that statement carry no term for?', '["The ambient temperature, which the balance treats as a boundary condition imposed only at the far end of the run.", "Pressure, time and phase change.", "The overall coefficient, which reaches the arrival through the relaxation length rather than through the balance itself.", "The bore diameter, which the profile recovers afterwards from the reference the coefficient was quoted against."]'::jsonb, 1, 'With the ambient fixed the solution is an exponential in the excess and nothing else, which is why the published arrivals carry no Joule-Thomson term at all.'),
  ('flowassurance', 'intermediate', 'module', 'm01-steady-state', 2, 'TEACHING LINE AKASO SPUR runs 60000.0 ft at an ntu of 1.219288832549 with an inlet excess of 150.0000 degF over a 45.00 degF seabed. Where does it arrive?', '["89.316029952695 degF, the seabed plus the inlet excess multiplied by exp of minus that ntu, which is 0.295440199685.", "45.00 degF, because a line run past one transfer unit has given up all of its excess.", "150.0000 degF, since the excess is what the balance carries to the far end.", "It cannot be said without the pressure drop along the line."]'::jsonb, 0, 'The arrival excess is 44.3160299527 degF, and no pressures are passed on this run so the Joule-Thomson term is exactly zero.'),
  ('flowassurance', 'intermediate', 'module', 'm01-steady-state', 3, 'On the published 105600.0 ft profile the fluid drops 23.8220561287 degF across the first 5280.0000 ft station interval and 0.6884883567 degF across the last. Why do equal lengths of one pipe do such unequal duty?', '["The overall coefficient is highest near the inlet, where the bore side film is thinnest and the wall is carrying the most heat per foot of pipe it will carry anywhere.", "The station spacing is not uniform on a 21 station run, so the first interval covers a longer stretch of pipe than the last one does.", "The driving force is the excess over ambient itself, so the same wall at the same U hands over far more heat where the fluid is still hot.", "The seabed is warmer at the far end."]'::jsonb, 2, 'The ratio of those two drops is 34.60052142, which is the ratio of the two starting excesses and nothing about the pipe.'),
  ('flowassurance', 'intermediate', 'module', 'm01-steady-state', 4, 'Lc = m Cp / (U pi D). Which quantity does the relaxation length not contain?', '["The mass rate, which reaches the arrival only through the number of transfer units the line accumulates.", "The overall coefficient, which is handed to the profile separately from the relaxation length it produced.", "The bore diameter.", "The length of the pipe, so it is a property of a fluid moving through a build rather than of a route."]'::jsonb, 3, 'It is the distance over which the stream gives up 63.21205588 percent of its excess, and the actual pipe appears nowhere in it.'),
  ('flowassurance', 'intermediate', 'module', 'm01-steady-state', 5, 'The published fluid at 60000.0 lb/hr and Cp 0.50 through the insulated build has a golden relaxation length of 14154.02315291 ft. What does 120000.0 lb/hr give on the same build?', '["14154.02315291 ft, because the relaxation length is fixed by the build and the bore rather than by what is flowing through them.", "28308.04630582 ft, exactly twice.", "A shorter length, since a faster stream spends less time against the wall and therefore relaxes over less pipe than a slow one does.", "33969.65556698 ft, which is that case with its heat capacity raised as well."]'::jsonb, 1, 'Lc is exactly linear in mass rate: the second case over the first is 2.0000000000 against a mass rate ratio of 2.0000000000.'),
  ('flowassurance', 'intermediate', 'module', 'm01-steady-state', 6, 'Raising the heat capacity of the published fluid from 0.50 to 0.60 Btu/(lb degF) at 120000.0 lb/hr moves the golden relaxation length from 28308.04630582 ft to 33969.65556698 ft. What is that factor?', '["2.0000000000, the same factor the mass rate produces on this build.", "It is not a fixed factor and depends on the length of the line.", "1.2000000000, the heat capacity ratio exactly, because m and Cp sit alone on the numerator of m Cp over U pi D.", "1.87167561, which is what the trench is worth."]'::jsonb, 2, 'Rate and heat capacity move the relaxation length exactly linearly, and U and the diameter move it exactly inversely.'),
  ('flowassurance', 'intermediate', 'module', 'm01-steady-state', 7, 'What does relaxationLengthFt hand back for a zero U, a zero mass rate or a zero heat capacity?', '["A bare NaN, with no ok flag and no message.", "An object carrying ok false and the message that the profile needs a length, a mass rate, a heat capacity and a heat transfer coefficient.", "An Infinity, which the arrival then reads as a line that never gives up any of its excess along the whole run.", "Zero, which the number of transfer units afterwards divides into and reports as an arrival sitting exactly at ambient."]'::jsonb, 0, 'It is not an object, so a caller who checks ok has nothing to check, and the NaN then divides into ntu and reaches every station.'),
  ('flowassurance', 'intermediate', 'module', 'm01-steady-state', 8, 'The published fluid loses 17.01575427 percent of its excess over 5280.0 ft of the insulated build. What has it lost over 26400.0 ft?', '["Around five times as much, since the length is five times as long and each mile of a uniform line costs the same share of what entered it.", "17.01575427 percent, because a uniform build loses the same fraction per station interval everywhere along the pipe it is laid in.", "97.60164748 percent.", "60.64696293 percent, because exp of minus an ntu of 0.932597039935 leaves 39.35303707 percent of it."]'::jsonb, 3, 'Length buys cooling fastest while the fluid is still hot, and by 105600.0 ft only 2.39835252 percent of the excess is left.'),
  ('flowassurance', 'intermediate', 'module', 'm01-steady-state', 9, 'Every published relaxation length parts company with its golden at a relative difference of 7.240504e-9. What is that residue?', '["The tolerance the engine applies when it decides a relaxation length has converged, which comes out the same on all three published cases.", "The oracle working in metres and watts and converting once at the boundary, not a disagreement about physics.", "An error in the golden, which is why the shipped engine value rather than the oracle one is the number quoted throughout the course.", "Round off in the bore diameter."]'::jsonb, 1, 'The published arrivals show the same signature, agreeing to 1.004609e-9, 3.912144e-9 and 2.091692e-9 across the three lengths.'),
  ('flowassurance', 'intermediate', 'module', 'm01-steady-state', 10, 'Two lines differ in bore, rate and insulation and land on the same ntu. What do they share?', '["The same arrival in degF, whatever inlet each of them started from.", "The same relaxation length, since ntu is assembled out of it.", "The same fraction of their inlet excess at the far end, because once the inlet and the ambient are fixed the arrival depends on ntu and on nothing else.", "Nothing, until their overall coefficients are compared."]'::jsonb, 2, 'Six quantities go into U pi D L over m Cp and one dimensionless number comes out, and the arrival follows that number alone.'),
  ('flowassurance', 'intermediate', 'module', 'm01-steady-state', 11, 'At ntu exactly 1 the retained excess is exp(-1) = 0.367879441171. What does the module header take from that row?', '["That a line one relaxation length long has already arrived at ambient, which is why a route is kept shorter than one of them wherever the seabed allows it.", "That 63.21205588 percent of the pipe is doing all of the cooling and the rest of the run contributes nothing measurable.", "That the arrival on such a line is 63.21205588 degF.", "That one relaxation length of pipe costs 63.21205588 percent of the excess, which is the definition of the relaxation length restated."]'::jsonb, 3, 'One relaxation length of pipe is one transfer unit, and the two statements are the same statement.'),
  ('flowassurance', 'intermediate', 'module', 'm01-steady-state', 12, 'A line sits at ntu 4.0000 holding 2.5641894444 degF of excess over ambient. What does more insulation buy it?', '["Less than a degF, since ntu 5.0000 still holds 0.9433125799 degF.", "A proportional gain, because the excess remaining falls linearly with the coefficient once a line is long against its own relaxation length.", "Nothing whatsoever, because past ntu 4 the exponential has reached ambient exactly and there is no term left anywhere in the balance.", "The same gain it bought when the line stood at ntu 0.5000."]'::jsonb, 0, 'A line long against its relaxation length arrives at ambient whatever it started at, and the interesting design range is the middle of that sweep.'),
  ('flowassurance', 'intermediate', 'module', 'm01-steady-state', 13, 'One derived run has its ntu wrong by 42.209398 percent at every length. What is that error worth in degF?', '["13.55773419 degF at every length, because a fractional error in ntu carries through the exponential unchanged wherever the line ends.", "3.80418823 degF at 5280.0 ft and 15.39298092 degF at 105600.0 ft.", "Nothing at all, since a percentage error in a dimensionless group cannot be restated in degrees of temperature in the first place.", "42.209398 degF, the same figure read as a temperature difference against the ambient the run was made against."]'::jsonb, 1, 'ntu sits in an exponent, so a tolerance quoted on it is not a tolerance in degrees until you say where on the curve it lands.'),
  ('flowassurance', 'intermediate', 'module', 'm01-steady-state', 14, 'The published 105600.0 ft case was run at 2, 3, 5, 11, 21, 51, 101 and 501 stations. What moved?', '["The arrival tightened towards the 21 station value as the count was refined, by less than a hundredth of a degF at the finest of them.", "The relaxation length, which is recomputed at each station and therefore averages differently on a coarse run than on a fine one.", "Nothing in the arrival, which reads 43.35769344274401 degF on every one of those eight rows.", "The last station only."]'::jsonb, 2, 'The station count is a resolution setting: the difference from the 21 station arrival is 0.0000e+0 degF at every count.'),
  ('flowassurance', 'intermediate', 'module', 'm01-steady-state', 15, 'The published build is handed an inlet 20.0 degF below the 40.0 degF ambient. What comes back, and is it right?', '["ok = false, since the balance is written for a line losing heat and has no branch for one gaining it.", "ok = true and an arrival of 20.0 degF, the inlet held because no driving force exists.", "ok = true with a note recording that the run was reversed.", "ok = true and an arrival of 39.5203295082 degF, and it is right, because a line colder than its surroundings warms towards them on the same exponential."]'::jsonb, 3, 'The exponential does not know which way the heat is going, and the module needs no special case for the one direction that would have earned one.'),
  ('flowassurance', 'intermediate', 'module', 'm02-designing-to-a-target', 1, 'uForArrivalTemp solves U = m Cp ln((Tin - Ta)/(Tt - Ta)) / (pi D L). How does it reach its answer?', '["By marching the profile forward in small steps and adjusting the coefficient until the arrival lands within a tolerance of the target it was handed.", "By interpolating between the two nearest rows of the coefficient sweep it keeps for the published pipe, then refining once against the profile.", "By one rearrangement, with no iteration, no tolerance and no starting guess anywhere in it.", "By a secant search on ntu."]'::jsonb, 2, 'The logarithm is the exponential turned over, and the function also returns the implied ntu, which is the one the forward profile would report.'),
  ('flowassurance', 'intermediate', 'module', 'm02-designing-to-a-target', 2, 'Each U from the inverse was fed straight back into the forward profile. The round trip error is 0.0000e+0 degF on every target except the 60.00 degF one, which closes at 7.1054e-15 degF. What does that prove?', '["That the inverse is the same equation read backwards, which is floating point rather than method error, and it proves nothing about the model being right.", "That the inverse is a better model of the line than the forward profile is.", "That the coefficient it returned can be built out of foam, burial or rate.", "That the target was inside the range the goldens cover."]'::jsonb, 0, 'An inverse that closes to the last figure is telling you it is the same exponential, not that the exponential describes your line.'),
  ('flowassurance', 'intermediate', 'module', 'm02-designing-to-a-target', 3, 'The published fluid runs 180.0 degF in against a 40.0 degF ambient at 120000.0 lb/hr and Cp 0.5 through the 6.065 in bore over 26400.0 ft. What coefficient lands it on a 120.00 degF target?', '["0.481611808482 Btu/(hr ft2 degF), which is the coefficient that would land the same line on a 140.00 degF arrival instead of the one asked for.", "0.801009837807 Btu/(hr ft2 degF), at an implied ntu of 0.559615787935.", "1.212785515268 Btu/(hr ft2 degF), because the target excess of 80.00 degF over ambient sets the implied ntu at 0.847297860387 on this run.", "It depends on which insulation is chosen."]'::jsonb, 1, 'The forward profile run on 0.801009837807 arrives at 120.000000000000 degF, a round trip error of 0.0000e+0 degF.'),
  ('flowassurance', 'intermediate', 'module', 'm02-designing-to-a-target', 4, 'What does the inverse actually hand you when it succeeds?', '["A coefficient together with the foam thickness and conductivity that would deliver it on the pipe that was handed in.", "A coefficient and a statement of whether a wall like that is buildable at the burial depth the trench allows.", "A coefficient and the mass rate the field would have to sustain for the target to hold at that wall.", "A number in Btu/(hr ft2 degF) and nothing else."]'::jsonb, 3, 'The step from a 160.00 degF target to a 60.00 degF one asks the wall to move from 0.220644616732 to 2.785291634878, and which of foam, burial or rate delivers it is a question the function never sees.'),
  ('flowassurance', 'intermediate', 'module', 'm02-designing-to-a-target', 5, 'TEACHING LINE AKASO SPUR has an overall U of 0.452972856617 Btu/(hr ft2 degF) referred to its bore, and its 71.00 degF flowing hydrate boundary needs 0.651078288819. What does the ratio of 1.43734504 say?', '["That the thermal design could get that much worse before the arrival sat on the boundary, which is the same statement as the arrival being above it.", "That the line needs 1.43734504 times more insulation than it has, since the ratio reads as a shortfall in wall to be made up with thicker foam before the target can be entertained at all.", "That the arrival sits 1.43734504 degF above the boundary.", "That the boundary was measured to 1.43734504 times its stated value."]'::jsonb, 0, 'A margin in degF and a margin in U are one fact in two currencies, and the second is the one an insulation decision is argued in.'),
  ('flowassurance', 'intermediate', 'module', 'm02-designing-to-a-target', 6, 'On TEACHING LINE AKASO SPUR a 90.00 degF target needs 0.447282863507 Btu/(hr ft2 degF), a ratio of 0.98743856 to the U the line has. What does a ratio below one mean?', '["The line makes the target with 0.98743856 of its margin still unspent, which is the reading a designer takes to an insulation review.", "The target is unreachable at any wall, which is the same case the inverse refuses outright when a target is put at or below ambient.", "The line misses that target, and on this row it misses it only just.", "The inverse has returned a coefficient that cannot be built."]'::jsonb, 2, 'A ratio above one means the line may be worse insulated than that and still make the target, and 0.98743856 sits just the wrong side of it.'),
  ('flowassurance', 'intermediate', 'module', 'm02-designing-to-a-target', 7, 'A target arrival on TEACHING LINE AKASO SPUR needs a U above the one the line has. What is that equivalent to?', '["The line needing a heavier weight coat before the target can be considered, because the coefficient the inverse asks for is the one the coating alone controls on a buried run.", "The line arriving above that target already, since the inverse and the forward profile are one equation read two ways.", "The target being below the seabed temperature and therefore unreachable at any wall thickness the pipe could carry.", "The inverse having been run at the wrong length."]'::jsonb, 1, 'The 71.00 degF row needs 0.651078288819 against the 0.452972856617 the line has, and its arrival with heat loss only is 89.316029952695 degF.'),
  ('flowassurance', 'intermediate', 'module', 'm02-designing-to-a-target', 8, 'overallU reports referenceIdIn on every coefficient it builds. Which of its consumers accepts that field?', '["steadyStateProfile alone, which is why an arrival is the one quantity the reference cannot corrupt on a run.", "relaxationLengthFt and steadyStateProfile, leaving only the cooldown call to be paired with its diameter by hand.", "All three, which is why the pairing has never had to be the responsibility of whoever writes the calling code.", "None of them."]'::jsonb, 3, 'relaxationLengthFt, steadyStateProfile and cooldownTime each take a bare inside diameter, so keeping the pair together is the caller''s job and nothing complains when the caller does not.'),
  ('flowassurance', 'intermediate', 'module', 'm02-designing-to-a-target', 9, 'The published buried build reads 0.501513997498 Btu/(hr ft2 degF) against the 8.625 in coated outside diameter. That coefficient is handed to a consumer with the 6.065 in bore over 26400.0 ft. What comes back?', '["A relaxation length of 75347.484814 ft instead of 52983.477727 ft and an arrival of 138.61917975 degF instead of 125.06144556 degF, with no complaint anywhere.", "A refusal, because the diameter and the coefficient disagree.", "The correct answer, since the total resistance of 0.883057962117 is the same either way.", "A note on the return recording the reference that was used."]'::jsonb, 0, 'The relaxation length is out by 42.209398 percent, which is exactly the diameter ratio of 1.4220939819 and nothing else.'),
  ('flowassurance', 'intermediate', 'module', 'm02-designing-to-a-target', 10, 'Moving the target on the published fluid from 60.00 degF to 45.00 degF moves the coefficient needed from 2.785291634878 to 4.769573431949 Btu/(hr ft2 degF), and 41.00 degF asks for 7.073253258346. What shape is that?', '["Linear in the target, which is why a design can be priced by the degF once the first two points on the curve are known from a single run.", "Flattening as the target falls, since the last few degF of arrival sit where the exponential has almost nothing left to give up to the sea.", "Steeper without limit as the target approaches ambient, because the logarithm runs away as the target excess goes to zero.", "Bounded by the coefficient a bare steel wall gives."]'::jsonb, 2, 'The 41.00 degF target implies an ntu of 4.941642422609, and every degF of target arrival is more expensive than the one before it.'),
  ('flowassurance', 'intermediate', 'module', 'm02-designing-to-a-target', 11, 'On the published pipe the first quarter inch of foam wall divides U by 22.61753379, and the fourth quarter inch divides it by 1.28791107. Why does the return fall away like that?', '["The foam conductivity of 0.0900 Btu/(hr ft degF) rises with thickness as the outer layers of the coating run warmer than the inner ones do.", "The outside film takes a growing share of the stack as the coated diameter grows, so the added foam is competing against a resistance that is growing with it.", "The bare pipe row is the only one in the sweep that is a published build, so the ratios below it are not comparable with one another.", "A layer resistance goes as ln(Do/Di), so equal thickness added further out is less logarithm."]'::jsonb, 3, 'ln(7.125 / 6.625) is 0.0727593543 and ln(16.625 / 16.125) is 0.0305367239, a ratio of 2.38268370 for the same quarter inch of wall.'),
  ('flowassurance', 'intermediate', 'module', 'm02-designing-to-a-target', 12, 'Swapping 2.0 in of syntactic foam at k 0.0900 for aerogel at k 0.0120 multiplies the layer resistance by exactly 7.50000000. What does it do to U?', '["Multiplies it by 7.50000000 as well, since U is the reciprocal of the total resistance and the layer is what the total resistance is made of.", "Multiplies it by 7.42733831, because the films and the steel wall do not move when the insulation does.", "Leaves it where it was, because a conductivity change moves a share of the stack rather than the stack itself and the shares always sum to 100.", "Multiplies it by 2166.666667."]'::jsonb, 1, 'U goes from 1.3348791131 to 0.1797250990, and quoting a U ratio as though it were a k ratio is what puts that reading wrong.'),
  ('flowassurance', 'intermediate', 'module', 'm02-designing-to-a-target', 13, 'The published fluid over 26400.0 ft is asked for a 40.00 degF arrival against its 40.0 degF ambient, and then for a 39.00 degF one. What happens?', '["Both are refused with one reason, that a line cannot arrive above ambient no matter how well it is insulated and the target has to be above it.", "Both return a very large coefficient with ok true, because the logarithm grows without bound as the target excess shrinks towards zero and nothing in the function caps what it returns.", "The 40.00 degF row is accepted and the 39.00 degF row refused.", "Both return an Infinity with a note attached."]'::jsonb, 0, 'That is a physical limit rather than a numerical guard: ambient is where an infinitely long line ends up and no wall reaches past it.'),
  ('flowassurance', 'intermediate', 'module', 'm02-designing-to-a-target', 14, 'A 180.00 degF target and a 185.00 degF target are refused on the same published fluid, but not with the same sentence. What does the second sentence say?', '["That the target sits above the range of the published cases the inverse was validated against, so no coefficient is returned for it.", "That the target exceeds the coefficient ceiling the module carries, which is the same ceiling the concentration check applies elsewhere.", "That the fluid already enters below the target, so insulation is not the problem.", "That a line cannot arrive above ambient however well it is insulated."]'::jsonb, 2, 'One refusal says the target is unreachable and the other says the question was the wrong one, and a caller who catches only ok = false has thrown that away.'),
  ('flowassurance', 'intermediate', 'module', 'm02-designing-to-a-target', 15, 'What does no refusal in uForArrivalTemp cover?', '["A target above the inlet, which passes through as a negative coefficient.", "The reference diameter of the coefficient it is about to produce, and whether the rate it was handed is one the field will sustain.", "A target at ambient, which passes through as an Infinity.", "A zero length, which passes through as an arrival sitting exactly at the inlet temperature the run was given."]'::jsonb, 1, 'It also does not know that a boundary quoted to the nearest degF is a laboratory reading, and it will invert one into a coefficient quoted to twelve figures without comment.'),
  ('flowassurance', 'intermediate', 'module', 'm03-cooldown', 1, 'Flowing, the balance is m Cp dT/dx against the wall loss per foot. Shut in, it becomes (M Cp) dT/dt = -U A (T - Ta). What has replaced the mass rate?', '["The station spacing, which becomes a time step once distance has left the equation and the clock has taken its place in the balance.", "The heat capacity of everything that has to be cooled.", "The station spacing, which becomes the time step.", "The bore diameter, which enters twice on a shut in line because the stagnant film and the contents mass are both built on it."]'::jsonb, 1, 'Lumped capacitance takes one temperature for the whole content of the pipe and falls towards ambient on an exponential in time.'),
  ('flowassurance', 'intermediate', 'module', 'm03-cooldown', 2, 'The one published cooldown returns a no-touch time of 4.662724855250 hr from the engine against a golden 4.662725032604 hr. What is the difference?', '["3.803658e-8 relative, the oracle converting out of SI seconds at the boundary.", "A genuine disagreement about the lumped capacitance model, which the oracle solves as a marching integration and the engine as a closed form.", "The engine rounding its time constant before multiplying.", "The station table, which the golden runs to the target and the engine runs past it to one and a half times the answer."]'::jsonb, 0, 'The two time constants carry the same signature, 3.588690771912 hr against a golden 3.588690908413 hr.'),
  ('flowassurance', 'intermediate', 'module', 'm03-cooldown', 3, 'The published cooldown reports a time constant of 3.588690771912 hr. What is that number built from?', '["The start excess over the target excess, 150.0 degF falling against a 70.0 degF target, which the published case reports as a logarithm of 1.299282984130.", "The no-touch time of 4.662724855250 hr divided across the 25 stations the table returns.", "The heat capacity of 7.606369304989 Btu/(ft degF) divided by the conductance of 2.119538792399 Btu/(hr ft degF), both per foot of pipe.", "The insulated U of 1.334879072040 times the bore area."]'::jsonb, 2, 'tau is computed before the log term and does not depend on the start or the target, which is why it survives in the cases where the hours do not.'),
  ('flowassurance', 'intermediate', 'module', 'm03-cooldown', 4, 'A line of the same construction as the published cooldown case is built twice as long. What happens to its time constant?', '["It doubles, since twice the pipe holds twice the mass that has to give up its heat.", "It halves, since twice the wall area is exposed to the same seabed.", "It cannot be computed without the length of the line.", "Nothing, because both terms of M Cp over U A are per foot of pipe and the foot cancels, so a time constant is a property of a cross section."]'::jsonb, 3, 'The published constant of 3.588690771912 hr belongs to the cross section, and only the log term of the two temperatures is left to move.'),
  ('flowassurance', 'intermediate', 'module', 'm03-cooldown', 5, 'The published cooldown has a time constant of 3.588690771912 hr and an answer of 4.662724855250 hr. Why are they different numbers?', '["The log term of ln((150.0 - 40.0)/(70.0 - 40.0)) is 1.299282984130 rather than one.", "The time constant is quoted at the flowing coefficient and the answer at the stagnant one, which is the substitution a shut in line calls for.", "The answer includes the extra stations the table runs past the target, which the time constant does not.", "The time constant is the golden value and the answer is the engine value."]'::jsonb, 0, 'They coincide only when the excess has to fall by exactly a factor of e, which no laboratory boundary is going to arrange for you.'),
  ('flowassurance', 'intermediate', 'module', 'm03-cooldown', 6, 'The published cooldown uses the insulated U of 1.334879072040 Btu/(hr ft2 degF), which was built with a flowing bore. Rebuilt with the stagnant film it is 1.0580538200. What does that do to the answer?', '["Nothing, because cooldownTime rebuilds the coefficient from the layer list it was handed.", "It takes the no-touch time from 4.662724855250 hr to 5.8826629631 hr and the time constant from 3.588690771912 hr to 4.5276225695 hr, a factor of 1.26163631 on both.", "It shortens the answer, since a stagnant bore conducts heat away faster.", "It is refused, because a shut in line has no flowing film to quote."]'::jsonb, 1, 'cooldownTime takes whichever U it is handed and nothing in it asks where the U came from, and the flowing one errs towards leaving the line early.'),
  ('flowassurance', 'intermediate', 'module', 'm03-cooldown', 7, 'The inside film carries 0.53395165 percent of the published insulated resistance stack. What does it carry once the same build is read with a stagnant bore?', '["The same 0.53395165 percent, because a film coefficient is a boundary layer property that the shutdown does not reach.", "98.882128 percent, taking over the share the foam layer held while the line was still flowing against the wall.", "21.16107640 percent.", "Nothing, because the bore side film drops out of the stack entirely once there is no flow to sustain it."]'::jsonb, 2, 'The wall did not change and the bore side boundary layer did, which is why a design U cannot be carried straight from the steady state work into the cooldown call.'),
  ('flowassurance', 'intermediate', 'module', 'm03-cooldown', 8, 'cooldownTime returns 25 stations covering 1.5 times the answer. On the published case station 16 reads 70.0000000000 degF. What is station 24?', '["The point at which the line has settled at its 40.0 degF ambient and the table stops because there is nothing left to report.", "A limit the engine imposes on how far a cooldown may be extrapolated before the lumped assumption is judged to have failed.", "The target, since the table is built to end on it.", "55.6669890360 degF at 6.99408728 hr, the same exponential continued past the question that was asked."]'::jsonb, 3, 'Reading the last station as the end of the cooldown invents every hour between 4.66272486 and 6.99408728.'),
  ('flowassurance', 'intermediate', 'module', 'm03-cooldown', 9, 'overallU accepts an unbounded list of layers and cooldownTime has exactly two mass slots. On the published insulated build, how many of those slots does the foam fit into?', '["None of the two, and that foam carries 98.882128 percent of the resistance of the build.", "One, the shell slot, which the module fills with every layer outside the bore by default.", "Both, since the two slots are filled by resistance share rather than by position.", "One, and a warning is returned when the layer list is longer than two."]'::jsonb, 0, 'There is no slot for a coating, no helper that lumps one, and no warning anywhere when the layer list runs longer than the two masses.'),
  ('flowassurance', 'intermediate', 'module', 'm03-cooldown', 10, 'TEACHING LINE AKASO SPUR cools from 120.00 degF towards a 45.00 degF seabed to a 71.00 degF target. The API reading gives 9.1117122206 hr. What does folding its foam and weight coat into the shell slot give?', '["The same 9.1117122206 hr, since the coating was already in the coefficient.", "A shorter time, because the coating adds resistance and not heat capacity.", "32.3290993724 hr, because the heat capacity moves from 9.7528832283 to 34.6040264905 Btu/(ft degF) and the two no-touch times stand at 3.5480816986.", "A refusal, because the shell slot takes steel only."]'::jsonb, 2, 'The API reading leaves out 112.4591995215 lbm/ft, and the layers it leaves out carry 67.414840 percent of the resistance of that build.'),
  ('flowassurance', 'intermediate', 'module', 'm03-cooldown', 11, 'On TEACHING LINE AKASO SPUR the ratio of the two heat capacities and the ratio of the two no-touch times are the same number, 3.5480816986. Why?', '["The start and the target temperatures were moved with the mass to keep the two readings comparable against one another.", "The coefficient falls in proportion when the coating is lumped in, so the time constant and the hours move together as a pair.", "The station count of 25 is the same in both.", "The log term of 1.0593915755 is identical in both readings, so only M Cp moved."]'::jsonb, 3, 'That is why the whole finding can be stated as a ratio of heat capacities and needs no second temperature to state it.'),
  ('flowassurance', 'intermediate', 'module', 'm03-cooldown', 12, 'cooldownTime reads its masses as (contents?.massLbPerFt || 0) and NaN is falsy. What happens when only the contents slot is NaN on the published case?', '["It is refused with the message that a cooldown needs a heat capacity for what is cooling and a heat transfer coefficient, which is the same refusal both slots produce.", "ok = true, 1.2806433091 hr against the correct 4.6627248553 hr, and no note.", "The NaN propagates, so the hours, the time constant and every station in the table come back as NaN and an unchecked caller sees the failure at once.", "The shell slot is doubled to cover the missing term, which is the fallback the two mass helpers were written to support."]'::jsonb, 1, 'The guard only fires when the TOTAL heat capacity reaches zero, so both slots bad refuses correctly and one slot bad is short by exactly that slot''s share, here -72.534444 percent.'),
  ('flowassurance', 'intermediate', 'module', 'm03-cooldown', 13, 'TEACHING LINE AKASO SPUR stops with its far end at 64.1160299527 degF and its shut-in boundary at 78.00 degF. cooldownTime is asked for the time to fall from the first to the second. What does it return?', '["ok = true and -4.6959175559 hr, with a time constant of 8.6008917110 hr, no note and no error, from a log term of -0.5459803139.", "ok = false, with a reason naming the start against the target.", "ok = true and an Infinity, with an empty station list.", "ok = true and zero hours, because the line is already there."]'::jsonb, 0, 'It also returns 25 stations which run backwards in time and warm by 24.2422513458 degF on a line that has just been shut in against a colder seabed.'),
  ('flowassurance', 'intermediate', 'module', 'm03-cooldown', 14, 'Asked on the same teaching line for a 40.0 degF target below its 45.0 degF seabed, cooldownTime returns hours as Infinity, a time constant of 8.6008917110 hr, 0 stations and a written note. What does that branch demonstrate?', '["That an Infinity is what the module returns whenever the two temperatures it was handed cannot both be reached from where the line actually is.", "That the time constant is meaningless once the hours are, which is why it is suppressed on the negative case as well as on this one.", "The shape the missing branch should have had.", "That a target below ambient is the only pair of temperatures the function checks."]'::jsonb, 2, 'It guards the start against ambient and the target against ambient, and never the start against the target.'),
  ('flowassurance', 'intermediate', 'module', 'm03-cooldown', 15, 'Put the mirror of the backwards cooldown to uForArrivalTemp, an inlet of 64.1160 degF against a target of 78.00 degF. What does it do?', '["It returns the coefficient that would deliver the target, since the inverse holds everything but U still and the pair is admissible to it.", "It refuses, saying the fluid already enters below the target so insulation is not the problem.", "It refuses, saying a line cannot arrive above ambient no matter how well it is insulated, which is the same refusal a target at the seabed draws.", "It returns ok true with a negative coefficient."]'::jsonb, 1, 'Two functions in one file take opposite positions on one pair of temperatures, and neither of them knows the other has been asked.'),
  ('flowassurance', 'intermediate', 'module', 'm04-the-margin', 1, 'A flow assurance verdict is one subtraction. Who owns each end of it?', '["The engine owns both, since a profile that knows the fluid knows where it hydrates.", "The laboratory owns both, and the engine reproduces them.", "Neither is owned, because the subtraction is a returned field.", "The engine owns the arrival and a laboratory owns the boundary, and both module headers say the boundary is a fluid property the consumer supplies."]'::jsonb, 3, 'flowlineThermal says hydrate and wax boundaries come from a lab or a compositional flash, and hydrateInhibition says it does not compute where the boundary is in the first place.'),
  ('flowassurance', 'intermediate', 'module', 'm04-the-margin', 2, 'The three published arrivals are 156.177943871283 degF, 95.094251524883 degF and 43.357693442744 degF. Which of them is safe?', '["The first two, since both sit well above the hydrate boundary the goldens carry for the published fluid at those lengths.", "None of them is safe or unsafe, because no boundary was supplied to judge any of them against.", "The first only, because the other two arrive below the temperature the engine returns as the hydrate onset for the case.", "All three, since each of them returns ok true."]'::jsonb, 1, 'steadyStateProfile has no boundary field, no margin field and no verdict, and ok true means four inputs were present.'),
  ('flowassurance', 'intermediate', 'module', 'm04-the-margin', 3, 'TEACHING LINE AKASO SPUR arrives at 89.316029952695 degF against a 45.00 degF seabed and a 71.00 degF flowing boundary. Which of its two subtractions is a verdict?', '["The 18.3160299527 degF against the boundary.", "The 44.3160299527 degF excess over the seabed, since that is the temperature the line still has to give up before anything can go wrong in it.", "Both, because the seabed and the boundary are two ways of naming the same limit on how cold the fluid is allowed to get.", "Neither, without the 78.00 degF boundary."]'::jsonb, 0, 'The excess over the seabed is what the exponential is decaying towards, and reading it as a margin is the most common way an answer comes out cheerful and wrong.'),
  ('flowassurance', 'intermediate', 'module', 'm04-the-margin', 4, 'TEACHING LINE AKASO SPUR carries a safety margin of 5.00 degF. Where does that number come from?', '["The engine, which sets it from the ntu of the run and reports it beside the arrival on every profile it returns.", "The laboratory, which quotes it as the uncertainty band on the hydrate boundary it measured for this fluid.", "Operator policy.", "The goldens, which carry it as the tolerance every published arrival is checked against by the oracle."]'::jsonb, 2, 'There is no natural scale on a margin, and nothing in either module computes, stores or checks one.'),
  ('flowassurance', 'intermediate', 'module', 'm04-the-margin', 5, 'TEACHING LINE AKASO SPUR returns 21 stations over 60000.0 ft. Its margin against the 71.00 degF boundary is 124.0000000000 degF at one place and 18.3160299527 degF at another. What does that tell you?', '["That the margin is an average over the run.", "That the two figures disagree and one of them is wrong.", "That the profile crossed the boundary between them.", "A margin belongs to a station, so a margin quoted without saying which station it was read at is not an answer."]'::jsonb, 3, 'The first figure is the inlet and the second is the arrival, and both are true statements about the same line.'),
  ('flowassurance', 'intermediate', 'module', 'm04-the-margin', 6, 'On TEACHING LINE AKASO SPUR the station at 30000.00 ft reads 126.5316165233 degF. What is its margin against the 71.00 degF flowing boundary?', '["55.5316165233 degF, a subtraction the reader makes rather than a field the return carries.", "81.5316165233 degF, its excess over the seabed.", "18.3160299527 degF, the margin of the line.", "It is not defined away from the arrival."]'::jsonb, 0, 'The margins run 46.1727098527 degF at 36000.00 ft and 24.0626561939 degF at 54000.00 ft, and the profile is the only thing that carries them.'),
  ('flowassurance', 'intermediate', 'module', 'm04-the-margin', 7, 'With the inlet and the ambient held fixed, what does a margin have to travel through on the engine side?', '["The overall coefficient alone, since the mass rate and the heat capacity cancel out of the group once the length is divided into the relaxation length.", "ntu, and nothing else, so a change that does not move ntu does not move the arrival.", "The relaxation length alone, which is why a line quoted with the same Lc as another arrives at the same temperature whatever length it is run over.", "The station count and the resolution of the run."]'::jsonb, 1, 'ntu is the length measured in relaxation lengths, and the arrival depends on it alone once the two temperatures are set.'),
  ('flowassurance', 'intermediate', 'module', 'm04-the-margin', 8, 'A margin came out tight, so the published 105600.0 ft case is rerun at 501 stations instead of 21. What does that buy?', '["A firmer arrival, because the exponential is sampled more finely and the accumulated station error falls away as the spacing shrinks.", "A tighter margin, because the finer run resolves the last station interval where the temperature is changing most slowly of anywhere.", "Nothing, a difference of 0.0000e+0 degF.", "A different coldest station, because the minimum of the profile is only found where the run has stations to find it at."]'::jsonb, 2, 'The arrival is a closed form and reads 43.35769344274401 degF at 2 stations and at 501, so rerunning for resolution moves a number outside the group.'),
  ('flowassurance', 'intermediate', 'module', 'm04-the-margin', 9, 'The same published fluid and bore, three builds. Which way does the overall coefficient move a relaxation length?', '["Exactly in proportion, since a better insulated line loses its excess over a shorter distance than a bare one does.", "Not at all, since the relaxation length is a fluid property.", "As the square root of the coefficient ratio.", "Exactly inversely, so 105.9799311355 gives 356.55635841 ft and 0.7132000377 gives 52983.47772700 ft."]'::jsonb, 3, 'The foam is worth a U ratio of 79.39290539 on this pipe and the trench 1.87167561 more, and once one resistance dominates the next has little left to do.'),
  ('flowassurance', 'intermediate', 'module', 'm04-the-margin', 10, 'TEACHING LINE AKASO SPUR carries a flowing boundary of 71.00 degF and a shut-in boundary of 78.00 degF. Take the second instead of the first. What moves?', '["The arrival, the ntu and the relaxation length all move, because the boundary is one of the inputs the profile is solved against.", "The margin shrinks by the whole distance between those two numbers, and no engine output moves at all.", "Nothing, since the two boundaries describe the same fluid and the engine reads whichever of them is the more conservative of the pair.", "The overall coefficient, which is rebuilt against the higher boundary before the margin is taken."]'::jsonb, 1, 'Every hydrate temperature in this course is an input, so a margin quoted without the source of its boundary is half an answer.'),
  ('flowassurance', 'intermediate', 'module', 'm04-the-margin', 11, 'The published pipe with a 3.0 ft trench returns 5 terms and a U of 0.7455927364 Btu/(hr ft2 degF). The same trench entered as 0.3 ft returns 4 terms and 1.3348791131. What does the return say about it?', '["Nothing at all: ok is true, there is no note, and the answer matches the engine''s own no-burial build to 0.0000e+0 relative.", "It carries an error naming the trench depth.", "It carries a note that a term was dropped.", "It refuses, as a bad layer would."]'::jsonb, 0, 'The ground share silently removed is 44.145299 percent and the error in U is 79.035960 percent, and every margin built on that coefficient is confident and wrong.'),
  ('flowassurance', 'intermediate', 'module', 'm04-the-margin', 12, 'An outside-diameter coefficient is handed to a consumer with the bore and the arrival comes back 13.55773419 degF wrong. Which returned field would have caught it?', '["The ok flag, which is false whenever the diameter handed in disagrees with the reference the coefficient was built against.", "The total resistance, which changes with the reference and therefore differs between the two ways of expressing the same physical line.", "None that a consumer reads.", "The station table, whose pressure column is populated only when the coefficient and the diameter were taken from the same build."]'::jsonb, 2, 'overallU reports referenceIdIn and none of its three consumers accepts that field, and the total resistance of 0.883057962117 is identical on both references.'),
  ('flowassurance', 'intermediate', 'module', 'm04-the-margin', 13, 'A line has a comfortable flowing margin. What does that say about the same line once it stops?', '["Nothing, because the boundary moves once the line packs up.", "That the shut-in margin is at least as large, since a stopped line is no longer expanding across a pressure drop and therefore loses less temperature than a flowing one.", "That the cooldown call will refuse if the shut-in boundary is above where the line stopped, which is the guard the module applies to that pair.", "That the no-touch time is positive."]'::jsonb, 0, 'On TEACHING LINE AKASO SPUR the boundary moves to 78.00 degF, and cooldownTime asked to fall to it from 64.1160299527 degF returns -4.6959175559 hr with ok true and no note.'),
  ('flowassurance', 'intermediate', 'module', 'm04-the-margin', 14, 'steadyStateProfile refuses a zero length and a zero U with one message. What does ok = true tell you about everything else?', '["That the coefficient, the diameter and the length were all taken from one consistent build of one pipe, which is the pairing nothing anywhere in the module ever checks.", "That four inputs were present and positive, and nothing about whether they described the line you meant.", "That the arrival is inside the range the goldens were validated over.", "That the profile is monotone and the arrival is its coldest station."]'::jsonb, 1, 'A coefficient built against the wrong reference diameter returns ok true, and so does one whose trench was silently dropped.'),
  ('flowassurance', 'intermediate', 'module', 'm04-the-margin', 15, 'Which margin field does either module return?', '["A margin field on the profile, populated once a boundary is passed alongside the ambient the run was made against.", "A boundary field on the cooldown, since the target it was handed is a hydrate temperature by construction.", "There is no margin field, no boundary field and no verdict anywhere in either of them.", "A verdict flag on the inhibitor return, which the profile then reads."]'::jsonb, 2, 'The subtraction is the reader''s, at a station the reader chose, against a number the reader supplied.'),
  ('flowassurance', 'intermediate', 'module', 'm05-the-whole-line', 1, 'On the published buried build, U times its own reference diameter comes to 0.360463185702 Btu/(hr ft degF) per foot at the 6.065 in bore and 0.360463185702 at the 8.625 in coated outside diameter. What is that product?', '["The overall coefficient expressed per unit length, which is what the profile consumes once the reference diameter has been divided back out of it.", "The conductance of the insulation layer alone, since the films and the steel wall contribute nothing measurable to a coated build.", "The line itself, and pi times it is one over the total resistance.", "A coincidence of the two diameters on this pipe."]'::jsonb, 2, 'A conductance per foot of pipe does not care what area you name, so a U is that product divided by whichever diameter was named, in ft.'),
  ('flowassurance', 'intermediate', 'module', 'm05-the-whole-line', 2, 'The same 2.0 in syntactic foam layer holds a resistance of 0.4665266247 hr ft degF/Btu per foot on every build it appears in, while its share reads 98.88212788 percent, 52.83080440 percent and 78.37609570 percent. What does that show?', '["That a share is a property of a build and the resistance is a property of the layer, so U describes a build rather than a fluid.", "That the foam conductivity was entered differently on the three builds.", "That the share is the quantity to quote, because it is the one that is stable.", "That the three builds are the same line read at three lengths."]'::jsonb, 0, 'That share swings by tens of percentage points from one build to the next while the layer itself never moves, which is why a share has to be quoted with the build it belongs to.'),
  ('flowassurance', 'intermediate', 'module', 'm05-the-whole-line', 3, 'On the published 105600.0 ft profile every station falls, from 180.0000000000 degF to 43.3576934427 degF. Why is the coldest point the far end?', '["Because the ambient is coldest at the far end of any subsea route, which is the condition the profile is solved against.", "The profile is a single decaying exponential with no second term in it to make it turn.", "Because the overall coefficient rises along the line as the coating cools, so the last stretch of pipe loses heat fastest of any of it.", "Because the station table is sorted before it is returned."]'::jsonb, 1, 'That is a property of one term and one ambient rather than a fact about pipelines, and it stops holding the moment anything else enters the balance.'),
  ('flowassurance', 'intermediate', 'module', 'm05-the-whole-line', 4, 'On the published profile the first station interval costs 23.8220561287 degF and the last costs 0.6884883567 degF, a ratio of 34.60052142. Why is that not exp(ntu), which is 41.69528946 on this line?', '["Because exp(ntu) applies only to a line run at the published 21 stations and the ratio changes with the station count.", "Because the first interval carries a different coefficient, the bore film being thinnest where the fluid enters hottest.", "Because the last interval is measured to the arrival and the first from the inlet, so one of them is half an interval short of the other.", "The two intervals are equal in length, so what is left is the ratio of the two starting excesses, which is exp of ntu times nineteen twentieths."]'::jsonb, 3, '41.69528946 is the factor the whole-line excess falls by, inlet to arrival, and reaching for it gets a plausible number one station interval wrong.'),
  ('flowassurance', 'intermediate', 'module', 'm05-the-whole-line', 5, 'The published build is handed an inlet 20.0 degF below the 40.0 degF ambient and returns an arrival of 39.5203295082 degF. Where is that line coldest?', '["At its arrival, since the coldest point of a profile is the far end and the module needs no special case for the direction of the heat.", "Nowhere in particular, because a line warming towards ambient has no monotone profile and its stations are not ordered in temperature.", "At its inlet.", "At the station where the profile crosses ambient, which is where the driving force changes sign along the run."]'::jsonb, 2, 'Coldest at the far end is a statement about warm lines, and the exponential does not know which way the heat is going.'),
  ('flowassurance', 'intermediate', 'module', 'm05-the-whole-line', 6, 'What would have to enter the balance before the arrival stopped being the coldest station?', '["A second term, such as a Joule-Thomson expansion, or an ambient that changes along the route.", "A finer station count, which resolves a minimum that a 21 station run steps straight over because the interior of the line is sampled too coarsely.", "A larger ntu, since a long line turns back up towards ambient at the far end.", "A coefficient referred to the coated outside diameter instead of the bore."]'::jsonb, 0, 'No published case sets a pressure, so the term is exactly zero in every one of them, and the model takes one ambient for a whole length that was never one depth.'),
  ('flowassurance', 'intermediate', 'module', 'm05-the-whole-line', 7, 'A reader draws a straight line between the two ends of the published profile. What does that put at the halfway station?', '["The same value the profile carries there, because the exponential is very nearly straight over the middle of any line that is long against its relaxation length.", "Rather less than the profile carries there, because the exponential is convex and lies above any chord drawn across the two ends of it.", "Nothing that can be compared, since the interpolation is in distance and the profile is in transfer units.", "Half of the inlet excess, where the exponential leaves 0.154866150566 of it."]'::jsonb, 3, 'Interpolating between endpoints puts the middle of a line far warmer than it is, and the middle is where a tie-in, a spool or a shut valve sits.'),
  ('flowassurance', 'intermediate', 'module', 'm05-the-whole-line', 8, 'A tight margin comes back on the published case, so the run is repeated at 501 stations, and separately a first pass is quoted at 2 stations as provisional. What is wrong with each?', '["Nothing is wrong with either, since a coarse run is a genuine approximation and a fine one genuinely improves on it.", "Both, in opposite directions: the arrival is 43.35769344274401 degF at 2 stations and at 501.", "Only the coarse run is wrong, because the closed form is evaluated at the last station and a two station table has no interior to evaluate it on.", "Only the fine run is wrong, since 501 stations are interpolated."]'::jsonb, 1, 'Stations are a resolution setting: the difference from the 21 station arrival is 0.0000e+0 degF at every count in the sweep.'),
  ('flowassurance', 'intermediate', 'module', 'm05-the-whole-line', 9, 'TEACHING LINE AKASO SPUR runs 21 stations against a 71.00 degF flowing boundary, with an inlet margin of 124.0000000000 degF and an arrival margin of 18.3160299527 degF. What is the finding?', '["That every station between the two ends is outside the boundary as well, which only the profile carries.", "That both ends are outside the boundary, which is the pair of numbers a design case is signed off against once the inlet and the arrival are known.", "That the margin at the arrival is the one to report, because it is the smallest.", "That the line crosses the boundary somewhere in the middle of the run."]'::jsonb, 0, 'The station at which this line first falls below 71.00 degF is none of the 21, and the coldest point is the arrival at 89.31602995 degF.'),
  ('flowassurance', 'intermediate', 'module', 'm05-the-whole-line', 10, 'A derived sweep on a 180.0 degF inlet against a 40.0 degF ambient gives 91.5031217640 degF at ntu 1.0000 and 58.9469396531 degF at ntu 2.0000. What does an arrival on its own identify?', '["The overall coefficient, which can be recovered from the arrival once the inlet and the ambient are known.", "The relaxation length, which the arrival fixes uniquely for a given inlet.", "The length, since the arrival is the closed form evaluated at it.", "Nothing about the line, because ntu is a group of five quantities and any combination of them that lands on it gives that arrival."]'::jsonb, 3, 'Two very different lines can hand back the same arrival, and the number itself carries no record of the build that produced it.'),
  ('flowassurance', 'intermediate', 'module', 'm05-the-whole-line', 11, 'A colleague sends a bare arrival temperature and nothing else. What cannot be recovered from it?', '["Only the station it belongs to, since the other three are fixed the moment the inlet and the ambient are quoted alongside the arrival, and a reader can work them back out from the closed form.", "Only the reference diameter, which is the single field the profile return has no room to carry back to a reader.", "Which station it belongs to, which line produced it, which diameter its coefficient was referred to, and whether that coefficient described the line at all.", "Nothing, because the arrival is a closed form and a closed form can be inverted for whatever quantity is missing."]'::jsonb, 2, 'The published buried build reads 0.713200037662 against the bore and 0.501513997498 against the coated outside diameter, and the same trench entered at a tenth of its depth reads 1.3348791131 instead of 0.7455927364.'),
  ('flowassurance', 'intermediate', 'module', 'm05-the-whole-line', 12, 'The profile returns nothing that names a build. What check does the API actually offer against a coefficient that describes a different pipe?', '["Comparing the total resistance against the reference diameter, which differ between two expressions of one line and therefore catch a mismatched pair.", "Counting the entries in the resistances array against what was handed in.", "Reading the ok flag, which the module sets false whenever a term it expected to compute could not be resolved from the inputs it was handed.", "Reading the note field on the return."]'::jsonb, 1, 'Two films, one entry per layer and one burial entry if a trench was asked for, and a trench of 3.0 ft entered as 0.3 ft comes back with 4 entries instead of 5.'),
  ('flowassurance', 'intermediate', 'module', 'm05-the-whole-line', 13, 'relaxationLengthFt refuses a zero U, a zero mass rate and a zero heat capacity. What is wrong with how it refuses?', '["It refuses as a bare NaN, so there is no ok field to test.", "It refuses with a message naming only the first of the three inputs it found missing, so a caller repairing one input has to call again to discover the next.", "It refuses with an object whose error text belongs to the profile rather than to the relaxation length, so the message names inputs the caller never supplied.", "It does not refuse at all, and returns an Infinity that the exponential afterwards reads as an arrival sitting exactly at the inlet temperature."]'::jsonb, 0, 'An unchecked caller carries the NaN into an ntu, an arrival and a margin, and the conductivity helper in the same file states the discipline this breaks.'),
  ('flowassurance', 'intermediate', 'module', 'm05-the-whole-line', 14, 'The profile hands back stations and an arrival. Which field does it use to report the coldest point?', '["The minimum field, which the module fills once the station table has been assembled and scanned for its lowest row.", "The arrival field, which the module documents as the coldest station of any run it returns and updates when a second term is present.", "There is none, and nobody notices because with one ambient and no pressure term the answer is always the last station.", "The station index carried on the return beside the relaxation length and the ntu."]'::jsonb, 2, 'Finding the coldest of the stations is the reader''s work, and it becomes real work the moment a second term enters the balance.'),
  ('flowassurance', 'intermediate', 'module', 'm05-the-whole-line', 15, 'Which quantity in this course will steadyStateProfile never compute, however it is called?', '["The relaxation length, which is supplied to it rather than derived by it.", "The number of transfer units, which the caller forms from the length.", "The total resistance, which only overallU returns.", "The hydrate boundary, which flowlineThermal says is a fluid property that comes from a lab or a compositional flash."]'::jsonb, 3, 'There is no boundary field, no margin field and no verdict in anything the profile returns, and ok true is a statement about four inputs.'),
  ('flowassurance', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'A professional reading is one exponential taken three ways: forwards to an arrival, backwards to a coefficient, and in time once the pumps stop. Which input appears in all three?', '["The overall coefficient, which sets the relaxation length, is what the inverse solves for, and divides into the time constant.", "The mass rate, which is in all three.", "The length, which is in all three.", "The hydrate boundary, which is in all three."]'::jsonb, 0, 'Lc is m Cp over U pi D, the inverse returns a U, and tau is M Cp over U A, so one quantity carries the whole reading.'),
  ('flowassurance', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'In what order should a screen be worked, and why does the boundary come first?', '["Boundary last, once the arrival and the no-touch time are in hand, so that the laboratory number can be chosen against the answers the engine has already returned for the line.", "Boundary first, because the profile takes it as an input and cannot form an arrival until a hydrate temperature has been supplied to it alongside the ambient.", "Boundary first, because it is the only number in the reading that no engine produces and every verdict is conditional on it.", "It makes no difference to the answer."]'::jsonb, 2, 'Record the flowing and the shut-in boundary with their source, and treat every margin as conditional on them.'),
  ('flowassurance', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'The stack has been built. What is counted next, and against what?', '["The station count against the length, so that the spacing of the profile divides the run into intervals of a size a reader can compare across two different lines.", "The resistances entries against what was handed in: two films, one per layer, and one burial entry if a trench was asked for.", "The shares against 100 percent, which is the check that catches a term the module was unable to compute and dropped without saying so.", "The layers against the two mass slots."]'::jsonb, 1, 'A trench shallower than half the coated diameter comes back NaN, is caught and dropped, and the exposed line returns ok true with no note. That floor is 0.35937500 ft on the published 8.625 in coated diameter.'),
  ('flowassurance', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'What is the arithmetic check that a coefficient and the diameter travelling with it belong together?', '["U times pi times the reference diameter, which is the total resistance itself on either reference.", "U divided by its reference diameter in ft, which is the conductance per foot of pipe and is the same number on both.", "U times the square of the reference diameter, which is the conductance per foot and does not move with the reference.", "U times its reference diameter in ft, which is 0.360463185702 on the published buried build whichever reference is named, and pi times that is the reciprocal of the total resistance."]'::jsonb, 3, 'A conductance per foot of pipe does not care what area is named, so the product survives the reference and the coefficient does not.'),
  ('flowassurance', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'Why is the relaxation length computed and checked before anything else in the forward pass?', '["It is exactly linear in mass rate and heat capacity, so an order of magnitude slip shows there and nowhere later.", "It is the only quantity the goldens publish twice, once from the oracle in SI and once from the shipped engine in field units, so it is the one number with an independent check standing behind it.", "It is the input the profile takes in place of a length.", "It is the quantity the inverse returns."]'::jsonb, 0, 'Doubling the rate multiplies it by 2.0000000000 and raising Cp from 0.50 to 0.60 multiplies it by 1.2000000000, and both are checks a reader can make in their head.'),
  ('flowassurance', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'What are stations run for?', '["Accuracy, since the arrival tightens as the count rises and a coarse run is only ever a provisional answer to be firmed up later.", "Both, because the arrival is evaluated at the last station and a finer table therefore places that station more precisely along the run.", "Shape, never accuracy.", "Neither, since the arrival is a closed form and the table adds nothing a reader of the two endpoints does not already have."]'::jsonb, 2, 'The published arrival is 43.35769344274401 degF at 2 stations and at 501, a difference of 0.0000e+0 degF, and what the table adds is the middle of the line.'),
  ('flowassurance', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'The inverse is run last and its coefficient is put back through the forward profile. What does a dirty round trip mean?', '["That the target sits too close to ambient for the logarithm to be evaluated to the precision the round trip is being checked at.", "That the inverse and the profile use different models, one closed form and one marched, so a residual of a few thousandths of a degF is expected.", "That the mass rate will not be sustained.", "That the diameter or the length disagrees between the two calls."]'::jsonb, 3, 'On the published fluid over 26400.0 ft a 120.00 degF target needs 0.801009837807 Btu/(hr ft2 degF) and the forward run returns 120.000000000000 degF, an error of 0.0000e+0 degF.'),
  ('flowassurance', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'What is checked first on a shutdown, before any hours are taken?', '["The ambient against the target, which is the one comparison cooldownTime does not make for itself and the one that produces an Infinity when it fails.", "The start against the target.", "The coefficient against the reference diameter, since a cooldown consumes a bare bore and cannot see which area the coefficient was quoted against.", "The station count against the answer, because the table is built to one and a half times the hours and a short table means the answer was clipped."]'::jsonb, 1, 'If the target is higher there is no no-touch time, and the function will not say so: on one such pair it returned -4.6959175559 hr with ok true.'),
  ('flowassurance', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'The time constant has been taken as M Cp over U A. What is recorded beside it?', '["Which layers were put into the two mass slots, because lumping a coating in moved one teaching cooldown by 3.5480816986.", "The station count of the table.", "The ambient the run was made against.", "The relaxation length of the flowing case."]'::jsonb, 0, 'That factor is worth 23.2173871518 hr on that line, and the API reading is not the conservative one.'),
  ('flowassurance', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'A professional reading produces four numbers. Which of them rests on a decision rather than on a computation?', '["The relaxation length, which rests on whichever reference diameter somebody chose to quote the coefficient against before the profile was ever run on it.", "The number of transfer units, which rests on the station count a reader picked and therefore carries a resolution decision into every arrival that follows from it.", "The arrival, which is fixed by the closed form but reported at whichever station a reader decided was the far end of the line they meant to describe.", "The mass that fills the two cooldown slots."]'::jsonb, 3, 'cooldownTime has two slots and no slot for a coating, and folding one in multiplied a teaching no-touch time by 3.5480816986.'),
  ('flowassurance', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'Which of the two boundaries is a cooldown measured against, and why?', '["The flowing one, because it is the boundary the steady state margin was taken against and the two answers have to be quoted on one basis.", "Whichever of the two is lower, so that the no-touch time reported to an operations room is the conservative of the two available readings.", "The shut-in one, which is the higher, because a line packs up after it stops.", "Neither, because the cooldown target is a temperature the module derives."]'::jsonb, 2, 'On the teaching line the boundary moves from 71.00 degF flowing to 78.00 degF once the line packs up, and no engine number moves with it.'),
  ('flowassurance', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'Which of these does the pair of modules genuinely earn?', '["A hydrate boundary computed from the fluid it was handed, which is the number every other quantity in the reading is measured against and the one the goldens publish for each case.", "An arrival that needs no marching, an inverse that round trips to 0.0000e+0 degF, and a cooldown with a time constant under it.", "A margin field on the profile return, populated once a boundary has been supplied to the call.", "A verdict on whether a line is safe."]'::jsonb, 1, 'The golden arrivals are 156.177944028181 degF, 95.094251896906 degF and 43.357693533435 degF at golden ntu of 0.186519406637, 0.932597033183 and 3.730388132730, and none of them is a verdict.'),
  ('flowassurance', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'Where do these modules refuse well?', '["uForArrivalTemp answers two impossible targets in two different sentences, and cooldownTime handles a target below ambient with an Infinity, a meaningful time constant, an empty station list and a written note.", "Nowhere, since every refusal in either of them is a bare NaN.", "On a trench shallower than half the coated diameter.", "On a coefficient referred to the wrong diameter."]'::jsonb, 0, 'A line cannot arrive above ambient however well it is insulated, and the fluid already enters below the target so insulation is not the problem, are two different findings.'),
  ('flowassurance', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'After the boundary, what is the second thing these modules hand over to the reader rather than computing?', '["The relaxation length, which the caller has to form before the profile can be given the length it is to be run over on that build.", "The number of transfer units, which no function in either module returns and which the reader assembles from the length and the coefficient by hand.", "The mass, because cooldownTime has two slots and no slot for a coating.", "The station spacing."]'::jsonb, 2, 'On a teaching gas line folding the insulation and the weight coat into the shell slot multiplies the no-touch time by 3.5480816986.'),
  ('flowassurance', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'What is ok = true a statement about?', '["The answer, since a module that could not describe the line it was handed would have set the flag false and returned a reason with it.", "The build, since the flag is set once the resistance stack has been assembled and every term in it resolved to a finite number.", "The boundary, since a profile given a hydrate temperature it cannot reach reports the failure through that flag rather than through a note.", "The inputs, not the answer."]'::jsonb, 3, 'A 3.0 ft trench entered as 0.3 ft returns U 79.035960 percent high with ok true and no note, and a cooldown to a target above its start returns -4.6959175559 hr the same way.'),
  ('flowassurance', 'intermediate', 'final', null, 1, 'A screen is worked in this order: the arrival, then the inverse against the boundary, then the shutdown. On TEACHING LINE AKASO SPUR the forward ntu is 1.219288832549 and the inverse against its 71.00 degF boundary implies 1.752538756075. What has the second number told you that the first did not?', '["That the forward run was made at the wrong length.", "That the boundary is unreachable on this line.", "How many more transfer units the line would have to accumulate before its arrival sat on the boundary, which is the same statement as the margin expressed in U rather than in degF.", "That the two calls disagree about the fluid."]'::jsonb, 2, 'The U needed is 0.651078288819 against the 0.452972856617 the line has, a ratio of 1.43734504, and the arrival is 89.316029952695 degF against a boundary of 71.00 degF.'),
  ('flowassurance', 'intermediate', 'final', null, 2, 'The relaxation length and the cooldown time constant are the same exponential with distance traded for time. What survives that trade and what does not?', '["The overall coefficient survives in both, and the mass rate is replaced by the mass of everything that has to be cooled.", "The mass rate survives in both, since a cooldown is the flowing balance evaluated at the rate the line was carrying at the moment it stopped, and the coefficient is what changes when the bore goes stagnant against the wall.", "Neither survives, because the two are separate models.", "The length survives, and the coefficient is replaced."]'::jsonb, 0, 'Lc is m Cp over U pi D and tau is M Cp over U A, and only one of the two has a clock in it.'),
  ('flowassurance', 'intermediate', 'final', null, 3, 'uForArrivalTemp refuses an inlet of 64.1160 degF against a target of 78.00 degF. cooldownTime is handed the same pair and returns -4.6959175559 hr with ok true. What should a caller take from that?', '["That the two functions model different physics, so the pair is admissible to one of them and not to the other, which is why the messages differ between the two returns.", "That the negative hours are the cooldown''s way of signalling the same refusal in a different currency, and taking the magnitude recovers the intended answer.", "That the pair is only a problem for the inverse.", "That the check has to be made before the call, because one function in the file makes it and the other does not."]'::jsonb, 3, 'The honest answer is that there is no no-touch time at all: the line is inside the shut-in envelope from the moment it stops.'),
  ('flowassurance', 'intermediate', 'final', null, 4, 'A line is reported with a comfortable flowing margin and a no-touch time of a few hours. Which of those two numbers can be wrong while every other engine output on the run looks entirely normal?', '["Neither, since a margin and a no-touch time are the two quantities the modules compute end to end from the pipe and the fluid they were handed.", "Both, because both are measured against a laboratory number.", "Only the margin, because the cooldown target is derived by the module from the ambient and the start temperature rather than supplied to it.", "Only the no-touch time, because the flowing margin is checked against the profile stations and any crossing between them would be reported."]'::jsonb, 1, 'The flowing boundary of 71.00 degF and the shut-in boundary of 78.00 degF on the teaching line are both inputs, and no engine output moves when either of them does.'),
  ('flowassurance', 'intermediate', 'final', null, 5, 'An outside-diameter coefficient is paired with a bore. The relaxation length comes back wrong by 42.209398 percent at every length, and the arrival wrong by 3.80418823 degF at 5280.0 ft and 15.39298092 degF at 105600.0 ft. Why do those two errors behave so differently?', '["The error in the relaxation length is a fixed ratio, and the arrival carries it through an exponential, so what it is worth in degF depends on where the line already sits on its own curve.", "The arrival error grows because the ambient changes with length.", "The two errors are the same error quoted in two units.", "The relaxation length error is a rounding and the arrival error is real."]'::jsonb, 0, '42.209398 percent is exactly the diameter ratio 1.4220939819, and the correct arrival at 26400.0 ft is 125.06144556 degF against a mixed 138.61917975 degF.'),
  ('flowassurance', 'intermediate', 'final', null, 6, 'The published 105600.0 ft profile drops 23.8220561287 degF over its first station interval and 0.6884883567 degF over its last, a ratio of 34.60052142. What two facts have to be combined to predict that ratio?', '["The station count and the ambient, since each interval carries the same fraction of the excess and the ambient sets what fraction of the inlet that excess is at the far end of the run.", "The relaxation length and the total length, which give exp(ntu).", "The coefficient and the bore, which give the conductance.", "The ntu of the whole line and the number of station intervals, since the ratio is exp of ntu times nineteen twentieths."]'::jsonb, 3, 'exp(ntu) on this line is 41.69528946 and it is the factor the whole-line excess falls by, which is one station interval away from the ratio of the two drops.'),
  ('flowassurance', 'intermediate', 'final', null, 7, 'A time constant does not move when a line of the same construction is built twice as long, and an arrival does. What separates them?', '["The cooldown is solved as a closed form and the profile as a march, so the profile accumulates a dependence on length that the closed form has no way of carrying into its answer.", "tau is built from two per foot quantities so the foot cancels, while the arrival depends on the length through ntu.", "The cooldown uses a stagnant coefficient and the profile a flowing one, and only the flowing one is quoted per unit of area rather than per unit of pipe.", "The cooldown has no ambient in it."]'::jsonb, 1, 'M Cp over U A is a property of a cross section, and only the log term of the two temperatures is left to move on a shutdown.'),
  ('flowassurance', 'intermediate', 'final', null, 8, 'A margin of 18.3160299527 degF and a ratio of 1.43734504 in the coefficient are one fact about TEACHING LINE AKASO SPUR. Which currency does an insulation decision get argued in?', '["The degF, because a hydrate boundary is quoted in degF and a design has to be defended in the units the laboratory measured its number in.", "Neither, because a margin is not a design quantity until an operator policy margin such as the 5.00 degF one has been subtracted from it first.", "The ratio, because that is what a wall is specified in.", "Both equally, since the two are computed from the same run and a reader can convert freely between them at any station along the line."]'::jsonb, 2, 'The ratio says how much worse the thermal design could get before the arrival sat on the boundary, which is the question a foam thickness answers.'),
  ('flowassurance', 'intermediate', 'final', null, 9, 'The published fluid at 120000.0 lb/hr and Cp 0.5 arrives at 156.177943871283 degF over 5280.0 ft, 95.094251524883 degF over 26400.0 ft and 43.357693442744 degF over 105600.0 ft. Which of them is closest to a hydrate blockage?', '["The last, at 43.357693442744 degF.", "The first, since it retains the most excess.", "The middle one, at 95.094251524883 degF.", "The question cannot be answered, because no hydrate boundary was supplied for the published fluid and neither module computes one."]'::jsonb, 3, 'steadyStateProfile has no boundary field, no margin field and no verdict, and ok true says four inputs were present.'),
  ('flowassurance', 'intermediate', 'final', null, 10, 'The published cooldown is run at the flowing insulated U of 1.334879072040 and then at the stagnant-bore U of 1.0580538200 Btu/(hr ft2 degF). Which answer goes into a shutdown procedure, and which way does the other one err?', '["The flowing one, because the coefficient a line is designed against is the one every other quantity in the reading was computed on and mixing coefficients between calls is the mistake to avoid.", "Either, since the two differ by a factor of 1.26163631 and that is inside the uncertainty of the boundary.", "The stagnant one at 5.8826629631 hr, and the flowing one at 4.662724855250 hr errs towards leaving the line early.", "Neither, because cooldownTime rebuilds the coefficient itself."]'::jsonb, 2, 'The wall did not change and the bore side boundary layer did: the inside film goes from 0.53395165 percent of the stack to 21.16107640 percent of it.'),
  ('flowassurance', 'intermediate', 'final', null, 11, 'Both ends of TEACHING LINE AKASO SPUR sit outside its 71.00 degF flowing boundary, at margins of 124.0000000000 degF and 18.3160299527 degF. What still has to be shown?', '["That every station between them is outside it too, which only the profile carries.", "That the two endpoint margins bracket the smallest margin on the line, which follows from the profile being a single decaying exponential with one ambient behind it.", "That the arrival was computed at the finest station count available, since a coarse run can step over a crossing that lies between two of its stations.", "Nothing further, since a monotone profile cannot dip."]'::jsonb, 0, 'On this line it is monotone and the coldest point is the arrival at 89.31602995 degF, and it is worth knowing that is why the endpoints were enough.'),
  ('flowassurance', 'intermediate', 'final', null, 12, 'What does the steady state balance have that the cooldown balance does not, and what does the cooldown have that the steady state does not?', '["A coefficient against a heat capacity, since the flowing balance is written on the wall conductance and the shut in one on the mass of the contents alone.", "Distance against time.", "An ambient against a target, since the flowing run decays towards a seabed and the shut in run decays towards a temperature the operator chose for it.", "A closed form against a march, since the arrival is evaluated in one step and the cooldown is stepped forward through its 25 stations to reach the hours."]'::jsonb, 1, 'The mass rate leaves and the heat capacity of everything that has to be cooled replaces it, and the exponential is otherwise the same exponential.'),
  ('flowassurance', 'intermediate', 'final', null, 13, 'TEACHING LINE AKASO SPUR is cooled from 120.00 degF to a 71.00 degF target against a 45.00 degF seabed. The API reading gives 9.1117122206 hr and the lumped reading 32.3290993724 hr. Which is conservative?', '["The API reading, since it leaves mass out.", "Neither is conservative, and the API reading is the short one by a factor of 3.5480816986 because the coating carries mass it has no slot for.", "The lumped reading, since it adds mass in.", "Both, since they bracket the true answer."]'::jsonb, 1, 'The layers left out carry 67.414840 percent of the resistance and 112.4591995215 lbm/ft, and the difference is 23.2173871518 hr.'),
  ('flowassurance', 'intermediate', 'final', null, 14, 'What changes about a relaxation length when the mass rate doubles and the heat capacity is then raised from 0.50 to 0.60 Btu/(lb degF)?', '["It is multiplied by 2.0000000000 and then by 1.2000000000, both exactly, because m and Cp sit alone on the numerator.", "It is multiplied by 2.0000000000 and then left where it is, because heat capacity enters the arrival through the number of transfer units rather than through the distance the fluid relaxes over.", "It is halved and then raised, since a faster stream relaxes sooner.", "It is unchanged in both, being a property of the build."]'::jsonb, 0, 'The golden cases run 14154.02315291 ft, 28308.04630582 ft and 33969.65556698 ft on the published insulated build.'),
  ('flowassurance', 'intermediate', 'final', null, 15, 'A trench of 3.0 ft is typed as 0.3 ft on the published pipe. What does the resistances array show, and what does the arrival built on it show?', '["The array shows 5 entries with the burial term set to zero, so a reader who counts the terms is reassured while the coefficient carries the whole of the error into the arrival.", "The array shows 4 entries and the profile return carries a note recording that a term could not be resolved from the trench that was handed in.", "Both show the error, because the total resistance is returned too.", "The array shows 4 entries instead of 5, and the arrival shows nothing at all."]'::jsonb, 3, 'The coefficient comes back 79.035960 percent high with ok true, matching the engine''s own no-burial build to 0.0000e+0 relative, and the ground share silently removed is 44.145299 percent.'),
  ('flowassurance', 'intermediate', 'final', null, 16, 'Which quantity has to be right before a relaxation length, an arrival, a no-touch time and a margin can be right?', '["The station count, since the resolution of the profile decides how finely each of the four quantities is resolved along the length of the line it was run on.", "The ambient, since it is the only input that appears identically in the flowing balance and the shut in one and therefore ties the two halves of the reading together.", "The coefficient, which every one of the four is built on.", "The heat capacity, since it appears in the relaxation length and in the lumped heat capacity and is the one input both halves of the reading share."]'::jsonb, 2, 'Lc is m Cp over U pi D, ntu divides into it, tau is M Cp over U A, and the margin is the arrival less a number no engine produced.'),
  ('flowassurance', 'intermediate', 'final', null, 17, 'The published inverse is asked for a 40.00 degF arrival against a 40.0 degF ambient, and separately for a 185.00 degF arrival on a 180.0 degF inlet. What separates those two refusals?', '["Nothing, since both return ok false.", "The first is a hard physical limit and the target is wrong, and the second says the line is already colder than the target so heating or rate is the problem and no insulation touches it.", "The first is refused and the second returns a negative coefficient.", "The first names ambient and the second names the length."]'::jsonb, 1, 'Same ok false, opposite corrective actions, and the message is the only thing that separates them.'),
  ('flowassurance', 'intermediate', 'final', null, 18, 'One relaxation length of pipe and one time constant of clock do the same thing to an excess. What is it?', '["They remove all of it, since a relaxation length is defined as the distance over which a stream reaches the ambient it has been losing heat to, and a time constant is the shut in equivalent of exactly that distance.", "They halve it.", "They leave 63.21205588 percent of it standing.", "They take 63.21205588 percent of it away, because exp(-1) is 0.367879441171 in both readings."]'::jsonb, 3, 'The flowing profile and the lumped cooldown are one exponential with time in place of distance and tau in place of Lc.'),
  ('flowassurance', 'intermediate', 'final', null, 19, 'A profile is rerun at 501 stations because a margin looked tight, and the same margin is quoted from a 2 station pass as provisional. What has each reader misunderstood?', '["That stations are resolution, since the arrival is 43.35769344274401 degF at both counts.", "That the closed form is evaluated at the last station, so both readers are right about the arrival and wrong only about the interior of the line between the two ends of it.", "That the station count changes the relaxation length, which is recomputed once per station and averaged across the table before the arrival is taken from it.", "That a margin is not a returned field."]'::jsonb, 0, 'The difference from the 21 station arrival is 0.0000e+0 degF at 2, 3, 5, 11, 21, 51, 101 and 501 stations.'),
  ('flowassurance', 'intermediate', 'final', null, 20, 'TEACHING LINE AKASO SPUR has an overall U of 0.452972856617 Btu/(hr ft2 degF) and a 90.00 degF target needs 0.447282863507, a ratio of 0.98743856. What does the line do against that target?', '["It makes it with 0.98743856 of its design margin still unspent, which is the number an insulation review is asked to sign off against for this line.", "It cannot be judged, because a ratio below one means the inverse returned a coefficient the line could not physically be built to carry.", "It misses it, and only just.", "It makes it comfortably, since a ratio close to one means the line and the target are effectively the same thermal design and either will do."]'::jsonb, 2, 'A ratio above one means the line may be worse insulated than that and still make the target, and this row sits just the wrong side of it.'),
  ('flowassurance', 'intermediate', 'final', null, 21, 'cooldownTime reads its two mass slots as (contents?.massLbPerFt || 0). One slot is handed a NaN. What comes back?', '["A refusal naming the slot.", "NaN hours and a NaN time constant.", "The other slot doubled to cover it.", "ok true, a full station table and hours short by exactly the dropped slot''s share of the heat capacity, with no note and no error to say so."]'::jsonb, 3, 'On the published case that is 1.2806433091 hr against the correct 4.6627248553 hr, -72.534444 percent, and both slots bad would have been refused correctly.'),
  ('flowassurance', 'intermediate', 'final', null, 22, 'Which of these did an engine in this course compute?', '["The arrival of 89.316029952695 degF on the teaching line.", "The 71.00 degF flowing hydrate boundary of that same line, which the profile reads alongside the ambient before it forms the excess the exponential decays from.", "The 5.00 degF safety margin carried with it.", "The 78.00 degF shut-in boundary it packs up to."]'::jsonb, 0, 'Both module headers say the boundary is a fluid property that comes from a lab or a compositional flash and the consumer supplies it.'),
  ('flowassurance', 'intermediate', 'final', null, 23, 'A relaxation length is reported as NaN and nobody notices until a margin comes out absurd. Where did the NaN enter and why was it not caught?', '["In steadyStateProfile, which refuses a zero coefficient and a zero length with one message and passes anything else through to the exponential without a further check on it.", "In relaxationLengthFt, which returns a bare NaN rather than an object, so there is no ok field to test.", "In overallU, which catches a NaN in the ground term and drops it, so the coefficient that reaches the relaxation length is finite and wrong rather than absent.", "In the ntu, which divides two finite numbers."]'::jsonb, 1, 'The conductivity helper in the same file states the discipline: a NaN propagates into a refusal, a plausible wrong number does not.'),
  ('flowassurance', 'intermediate', 'final', null, 24, 'The published cooldown returns a time constant of 3.588690771912 hr and an answer of 4.662724855250 hr. What is the whole of the difference between them?', '["The 25 stations the table runs to, which extend past the target to one and a half times the answer and therefore lengthen the reported hours accordingly.", "The substitution of the stagnant coefficient for the flowing one, which lengthens the answer without touching the time constant it was formed from.", "A log term of 1.299282984130.", "The difference between the golden reading in SI seconds and the engine reading in field hours, which is 3.803658e-8 relative on both quantities."]'::jsonb, 2, 'The no-touch time is 1.299282984130 time constants, and the two coincide only when the excess has to fall by exactly a factor of e.'),
  ('flowassurance', 'intermediate', 'final', null, 25, 'A line is short against its relaxation length and another is long against it. What does each of them arrive at?', '["Both arrive at ambient eventually.", "The short one arrives hot whatever the ambient is, and the long one arrives at ambient whatever it started at, because the arrival depends on ntu alone.", "Both arrive at their inlet, less the pressure term.", "It depends on the coefficient rather than on ntu."]'::jsonb, 1, 'At ntu 0.1000 the arrival is 166.6772385250 degF on a 180.0 degF inlet against a 40.0 degF ambient, and at ntu 5.0000 it is 40.9433125799 degF.'),
  ('flowassurance', 'intermediate', 'final', null, 26, 'A design is being argued between thicker foam and better foam on the published pipe. What does the sweep say each buys?', '["Thickness buys a fixed factor per inch and material buys 7.50000000, so the two can be traded against each other by the inch once the first inch has been laid on the pipe.", "Thickness buys nothing after the first inch and material buys everything.", "Both buy exactly what their conductivity ratio says they will.", "The first quarter inch of wall divides U by 22.61753379 and the fourth by 1.28791107, while aerogel against syntactic foam is worth 7.42733831 on U."]'::jsonb, 3, 'A layer resistance goes as ln(Do/Di) and is exactly inverse in k, and U follows neither exactly because the films and the steel do not move.'),
  ('flowassurance', 'intermediate', 'final', null, 27, 'The published cooldown station table runs to 25 rows. Station 16 reads 70.0000000000 degF and station 24 reads 55.6669890360 degF at 6.99408728 hr. Which row is the answer?', '["Station 16, at 4.66272486 hr.", "Station 24, because a station table is built to end on the temperature the call was asked about and the last row is therefore the answer by construction.", "Neither, because the table samples an exponential and the answer is interpolated between the two stations that bracket the target it was given.", "Station 24, because the table runs to one and a half times the answer."]'::jsonb, 0, 'Reading the last station as the end of the cooldown invents every hour between 4.66272486 and 6.99408728.'),
  ('flowassurance', 'intermediate', 'final', null, 28, 'TEACHING LINE AKASO SPUR runs 21 stations at 3000.00 ft spacing. At which of them does it first fall below its 71.00 degF flowing boundary?', '["At the arrival, which is the coldest station of any monotone profile and therefore the first and only crossing a line of this kind can have.", "None of the 21.", "At the station reading 95.0626561939 degF, which is where the margin first falls below the 24.0626561939 degF a shut in line would need.", "It cannot be said from the profile, since the return carries no field naming the coldest station or the first crossing of any boundary."]'::jsonb, 1, 'The coldest point is the arrival at 89.31602995 degF, and the verdict is safe because the profile is monotone.'),
  ('flowassurance', 'intermediate', 'final', null, 29, 'An arrival, a no-touch time and a margin are quoted from one screen. Which of the three is not an engine quantity at all?', '["The margin only.", "The no-touch time only.", "None of the three is purely an engine quantity, because the no-touch time carries a target and the margin carries a boundary, both of them laboratory numbers.", "All three are engine quantities."]'::jsonb, 2, 'The pipe half of a no-touch time is reproducible to eight figures across two implementations and the temperature half is a laboratory reading.'),
  ('flowassurance', 'intermediate', 'final', null, 30, 'What does ntu swallow, and what does it therefore fail to record?', '["It swallows the inlet and the ambient, which is why two lines at the same ntu arrive at the same temperature in degF whatever they started from and whatever seabed they were laid on.", "It swallows the length alone, which the relaxation length then restores.", "It swallows the station count, so a coarse run and a fine one give the same value.", "Six quantities go in and one dimensionless number comes out, so the arrival cannot say which combination produced it."]'::jsonb, 3, 'A derived sweep gives 91.5031217640 degF at ntu 1.0000 and 58.9469396531 degF at ntu 2.0000 whatever combination of the five quantities landed there.'),
  ('flowassurance', 'intermediate', 'final', null, 31, 'The inverse is asked for a 100.00 degF arrival on TEACHING LINE AKASO SPUR and returns 0.372732538977 Btu/(hr ft2 degF) at an implied ntu of 1.003302108864. What is the ratio of 0.82285844 for?', '["It compares that requirement against the coefficient the line already has.", "It compares the implied ntu of 1.003302108864 against the ntu of 1.219288832549 the forward run reports, which is the same comparison expressed in transfer units instead of in a coefficient.", "It records how much of the total resistance the insulation is carrying on this build, which is the share the inverse holds fixed while it moves the coefficient it returns.", "It is the round trip error of the inversion."]'::jsonb, 0, 'A ratio below one means the line arrives below that target, and this line arrives at 89.316029952695 degF.'),
  ('flowassurance', 'intermediate', 'final', null, 32, 'A 41.00 degF target on the published fluid asks for 7.073253258346 Btu/(hr ft2 degF) and a 45.00 degF target asks for 4.769573431949. Why does the requirement run away like that?', '["Because the coefficient the inverse returns is quoted against the bore, and a target close to the ambient forces the reference area down until the number expressed against it grows without limit.", "The target excess is heading for zero, so the logarithm has no bound.", "Because the ntu implied by such a target exceeds the range the module was validated over, and the returned coefficient is an extrapolation past the last published case.", "Because the mass rate is held fixed while the target moves, so the whole of the extra duty has to come out of the wall rather than out of the stream that is carrying it."]'::jsonb, 1, 'The 41.00 degF target implies an ntu of 4.941642422609, and no wall reaches the ambient at any thickness.'),
  ('flowassurance', 'intermediate', 'final', null, 33, 'One function runs happily on a stream that is colder than what surrounds it, and another refuses a target at or below ambient outright. Are those two positions consistent?', '["No, and the profile is the one in the wrong.", "No, and the inverse is the one in the wrong.", "Yes, because one is being asked what a line does and the other what wall would be needed, and no wall reaches past ambient however good it is.", "Yes, because both return ok true."]'::jsonb, 2, 'A line colder than its surroundings warms towards them on the same exponential, while a target the wall can never reach is a different question entirely.'),
  ('flowassurance', 'intermediate', 'final', null, 34, 'cooldownTime is asked for a target of 40.0 degF below the 45.0 degF seabed on the teaching line. What does the return look like, and why does it matter?', '["Infinity hours, a time constant of 8.6008917110 hr, an empty station list and a written note, and it matters because it is the shape the missing branch should have had.", "A refusal naming the target against the ambient, which is the guard the module applies to the start as well and is the reason the negative case cannot arise in practice on any real line.", "Zero hours and an empty table, since the line never leaves ambient.", "Negative hours, the same as a target above the start."]'::jsonb, 0, 'It guards the start against ambient and the target against ambient, and never the start against the target.'),
  ('flowassurance', 'intermediate', 'final', null, 35, 'Two engineers hand in the same physical line. One reports U as 0.713200037662 Btu/(hr ft2 degF) and the other as 0.501513997498. Who is wrong?', '["The second, since a coefficient referred to a coated outside diameter is not a coefficient any of the three consumers in the module will accept without a conversion first.", "Neither, because the two are the bore and the coated outside diameter references of one identical total resistance.", "The first, since a buried build has to be referred to the outside of the coating for the ground term to be dimensionally consistent with the layers inside it.", "Both, since a single line has one coefficient."]'::jsonb, 1, 'The ratio of 1.4220939819 is exactly the ratio of the two diameters, and the total resistance of 0.883057962117 is identical on both.'),
  ('flowassurance', 'intermediate', 'final', null, 36, 'Which returned field would have told a reader that a coefficient was built against a diameter the consumer did not use?', '["The resistances array, whose entry count changes with the reference the coefficient was expressed against and therefore records the choice for a reader who counts them.", "The total resistance, which differs between the two references and can therefore be compared against the diameter the consumer was handed alongside the coefficient.", "referenceIdIn, which no consumer accepts.", "The ok flag, which the module sets false when the diameter it is handed disagrees with the reference the coefficient carries in its own return."]'::jsonb, 2, 'relaxationLengthFt, steadyStateProfile and cooldownTime each take a bare inside diameter, so the pairing is the caller''s job and nothing complains when the caller does not do it.'),
  ('flowassurance', 'intermediate', 'final', null, 37, 'A no-touch time is reported to an operations room as a number of hours and nothing else. What has been left out?', '["The time constant.", "The station count of the table.", "The ambient the line was cooling towards.", "The target it was measured to, since the pipe half of the answer is reproducible to eight figures and the temperature half is a laboratory reading that decides whether a crew has hours or none."]'::jsonb, 3, 'On the teaching line the flowing boundary is 71.00 degF and the shut-in one is 78.00 degF, and picking the wrong one moves the whole answer with no engine number changing.'),
  ('flowassurance', 'intermediate', 'final', null, 38, 'A course reader asks why the goldens in this course never show a Joule-Thomson term. What is the answer, and what does it mean for the published profile?', '["The oracle computes the term and the engine does not, so the two would disagree on every published row and the comparison is made on heat loss alone to keep the goldens usable as a check.", "The term is folded into the coefficient before the profile is run.", "No published case sets any pressure, so the term is exactly zero and the pressure column reads n/a in all 21 stations.", "The published fluid is a liquid and does not expand."]'::jsonb, 2, 'That is also why the coldest point of every published profile is the far end and only the far end.'),
  ('flowassurance', 'intermediate', 'final', null, 39, 'The same 2.0 in of syntactic foam appears on four builds and reads 98.88212788 percent, 52.83080440 percent, 97.50919137 percent and 78.37609570 percent of the stack. What did not change across those four?', '["Its resistance of 0.4665266247 hr ft degF/Btu per foot.", "Its share, which is quoted differently on each build because each names a different reference diameter for the coefficient that the shares are computed against.", "The overall coefficient, which is the reciprocal of a total resistance the foam dominates on all four of those builds and therefore barely moves between them.", "Nothing, since a build is defined by its layers."]'::jsonb, 0, 'The spread of that share across those four builds is 46.05132348 percentage points while the layer itself never moved, which is why U describes a build rather than a fluid.'),
  ('flowassurance', 'intermediate', 'final', null, 40, 'What is the first thing to write down when a flow assurance screen is started?', '["The overall coefficient, since every other quantity in the reading is built on it and an error there propagates into the relaxation length, the ntu, the arrival and the hours alike.", "Both hydrate boundaries, each with its source.", "The relaxation length, since it is exactly linear in mass rate and heat capacity and an order of magnitude slip shows there and nowhere later in the reading.", "The station count, since the resolution of the profile has to be settled before the interior of the line can be compared against any boundary that is later supplied."]'::jsonb, 1, 'A line packs up after it stops, so the shut-in boundary is the higher and the one a cooldown is measured against.'),
  ('flowassurance', 'intermediate', 'final', null, 41, 'An inverse returns a coefficient and the forward profile run on it lands 0.0000e+0 degF from the target. What has been established?', '["That the coefficient is buildable.", "That the target is above the ambient.", "That the boundary was correctly chosen.", "That the two calls used the same diameter and the same length and are the same equation, and nothing whatever about whether that equation describes the line."]'::jsonb, 3, 'A dirty round trip means the diameter or the length disagrees between calls, and a clean one means only that they agree.'),
  ('flowassurance', 'intermediate', 'final', null, 42, 'Which pair of quantities in this course is reproducible to eight figures across two independent implementations, and which pair is not reproducible at all?', '["The relaxation length and the time constant are, and the arrival and the no-touch time are not, because both of the latter carry a logarithm of two temperatures that the oracle evaluates in a different unit system.", "All four are, since the oracle publishes every one of them.", "The arrival and the no-touch time are, and the hydrate boundary and the operator margin are not engine quantities to reproduce.", "None of them is, because the oracle works in SI."]'::jsonb, 2, 'A margin inherits the worse of its two ends, and the engine end is not the weak one.');
